// ─────────────────────────────────────────────────────────────────────────
//  05 · joining without the trailing slash                           ★☆☆
//  concepts: String.join · LinkedHashMap entry order · URLEncoder form encoding
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;

class Exercise {

    /** The parts joined with "/". */
    static String pathOf(List<String> parts) {
        return String.join("/", parts);
    }

    /** Form-encoded key=value pairs in the map's order, joined with "&". */
    static String query(LinkedHashMap<String, String> params) {
        var pairs = new ArrayList<String>();
        for (var e : params.entrySet()) {
            pairs.add(URLEncoder.encode(e.getKey(), StandardCharsets.UTF_8) + "=" + URLEncoder.encode(e.getValue(), StandardCharsets.UTF_8));
        }
        return String.join("&", pairs);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("pathOf joins segments with slashes", () ->
            eq(pathOf(List.of("api", "v2", "users")), "api/v2/users"));
        test("a single segment comes back unchanged (boundary)", () ->
            eq(pathOf(List.of("api")), "api"));
        test("query keeps parameter order", () -> {
            var params = new LinkedHashMap<String, String>();
            params.put("q", "java");
            params.put("page", "2");
            eq(query(params), "q=java&page=2");
        });
        test("query form-encodes keys and values", () -> {
            var params = new LinkedHashMap<String, String>();
            params.put("q", "a&b c");
            params.put("sort by", "price=asc");
            eq(query(params), "q=a%26b+c&sort+by=price%3Dasc");
