//  06 · slicing by anchors                                           ★★☆
//  concepts: String.indexOf · String.lastIndexOf · substring windows · -1 means absent
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Everything after the @. */
    static String domainOf(String email) {
        return email.substring(email.indexOf('@') + 1);
    }

    /** Everything after the last dot; "" when there is none or it is the last character. */
    static String extensionOf(String file) {
        int dot = file.lastIndexOf('.');
        if (dot < 0 || dot == file.length() - 1) return "";
        return file.substring(dot + 1);
    }

    /** The text between the first open and the first close after it; "" when either is missing. */
    static String between(String s, String open, String close) {
        int start = s.indexOf(open);
        if (start < 0) return "";
        start += open.length();
        int end = s.indexOf(close, start);
        if (end < 0) return "";
        return s.substring(start, end);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("domainOf slices after the @", () ->
            eq(domainOf("kai@dev.io"), "dev.io"));
        test("extensionOf uses the last dot", () ->
            eq(extensionOf("archive.tar.gz"), "gz"));
        test("no dot means no extension (boundary)", () ->
            eq(extensionOf("README"), ""));
        test("a trailing dot means no extension", () ->
            eq(extensionOf("notes."), ""));
        test("between finds the first window", () ->
            eq(between("a[b]c", "[", "]"), "b"));
        test("between with no closing marker is empty", () ->
            eq(between("a[bc", "[", "]"), ""));
        System.exit(report());
    }
